<a class="suggest-link" href="{{link}}" data-state="{{link}}" data-heading="{{comes_f}}"><div class="left-suggest-col" data-photo="{{photo}}" style="background:url(/images/SimplyPadreBusinessMemberPlaceHolder-250.jpg) center/contain no-repeat"><img src="{{/images/SimplyPadreBusinessMemberPlaceHolder-250.jpg}}" data-def="profile-profile-holder" onload="if(this.src.indexOf(this.dataset.def)>-1)this.style.opacity=0" data-state="{{photo}}"></div><div class="right-suggest-col" data-photo="{{photo}}"><p class="media-heading" data-state="{{value}}" data-heading="{{comes_f}}">{{value}}</p><p class="suggest-origin" data-state="{{comes_f}}">{{comes_f}}</p><p class="location" data-state="{{location}}">{{location}}</p></div></a>